#[test]
fn verify_agrees_with_the_oracle_on_twenty_live_documents() {
    let root = repo_root();
    let mut checked = 0;
    for (doc, want_exit, want_problems) in LIVE_VERIFY {
        if !root.join(doc).is_file() {
            // A live document that moved is not a parity failure; the pin is stale, and the
            // remaining nineteen still answer the question.
            continue;
        }
        let (code, out) = run_cites(&root, &["verify", doc]);
        assert_eq!(
            code, *want_exit,
            "{doc}: verify exit differs from the recorded oracle answer"
        );
        assert_eq!(
            out.matches("   - ").count(),
            *want_problems,
            "{doc}: verify problem count differs from the recorded oracle answer"
        );
        checked += 1;
    }
    assert!(
        checked >= 15,
        "only {checked} of the twenty live pins were resolvable"
    );
}

// ---------------------------------------------------------------------------
// (c) stamp writes exactly the strings the contract names, and is idempotent
// ---------------------------------------------------------------------------

/// The five `status:` strings the contract fixes. Changing one of these is a corpus-wide diff.
const CONTRACT_HINTS: &[(&str, &str)] = &[
    ("held", "held — target sequestered (see cluster-state.yaml)"),
    ("stale", "stale — target content moved on; re-verify"),
    (
        "remote",
        "remote — resolvable on the substrate, absent locally",
    ),
    ("dead", "dead — target no longer resolves"),
];

#[test]
fn stamp_writes_the_contract_strings_for_every_verdict() {
    let (_guard, root) = staged("stamp");
    let (code, out) = run_cites(&root, &["stamp", "--all", "--write"]);
    assert_eq!(code, 0, "stamp refused: {out}");
    // Counts, matching `cite-propagate.py --apply` on the same fixture (measured 2026-09-10).
    assert!(out.contains("7 docs"), "{out}");
    assert!(out.contains("status stamped: 4"), "{out}");
    assert!(out.contains("cleared (recovered/healthy): 1"), "{out}");
    assert!(out.contains("path: stamped/refreshed: 1"), "{out}");
    assert!(out.contains("docs touched: 2"), "{out}");

    let citer = std::fs::read_to_string(root.join("genesis/docs/superpowers/specs/citer.md"))
        .expect("read citer");
    for (verdict, hint) in CONTRACT_HINTS {
        assert!(
            citer.contains(&format!("status: {hint}")),
            "the {verdict} edge did not carry the contract string `{hint}`:\n{citer}"
        );
    }
    // `ok` REMOVES the field rather than writing one.
    let ok_line = citer
        .lines()
        .find(|l| l.contains("ok-target |"))
        .expect("ok edge present");
    assert!(
        !ok_line.contains("status:"),
        "an ok edge must carry no status: {ok_line}"
    );
    // A dead slug keeps its last known path as a forensic breadcrumb, never blanked.
    let dead_line = citer
        .lines()
        .find(|l| l.contains("gone-target |"))
        .expect("dead edge present");
    assert!(
        dead_line.contains("path: genesis/docs/superpowers/specs/gone-target.md"),
        "a dead slug must keep its breadcrumb path: {dead_line}"
    );
    // A legacy path cite is skipped entirely — its ref IS the path, it carries no status.
    assert!(
        citer.contains("  - elohim/elohim-storage/src/db/mod.rs"),
        "the legacy path cite was rewritten:\n{citer}"
    );
    // A recovered edge clears its stale hint and has its wrong locator refreshed.
    let second =
        std::fs::read_to_string(root.join("genesis/docs/superpowers/specs/second-citer.md"))
            .expect("read second citer");
    assert!(
        !second.contains("status:"),
        "the recovered edge kept a status hint:\n{second}"
    );
    assert!(
        !second.contains("WRONG/PLACE.md"),
        "the locator was not refreshed:\n{second}"
    );
}

#[test]
fn stamp_is_idempotent_and_byte_stable() {
    let (_guard, root) = staged("stamp");
    run_cites(&root, &["stamp", "--all", "--write"]);
    let before: BTreeMap<String, String> = ["citer.md", "second-citer.md"]
        .iter()
        .map(|f| {
            let p = root.join("genesis/docs/superpowers/specs").join(f);
            ((*f).to_string(), sha256_of(&p))
        })
        .collect();
    let (code, out) = run_cites(&root, &["stamp", "--all", "--write"]);
    assert_eq!(code, 0, "{out}");
    assert!(
        out.contains("status stamped: 0"),
        "second pass stamped again:\n{out}"
    );
    assert!(out.contains("cleared (recovered/healthy): 0"), "{out}");
    assert!(out.contains("path: stamped/refreshed: 0"), "{out}");
    assert!(out.contains("docs touched: 0"), "{out}");
    for (name, digest) in &before {
        let p = root.join("genesis/docs/superpowers/specs").join(name);
        assert_eq!(&sha256_of(&p), digest, "{name}: second stamp changed bytes");
    }
}

#[test]
fn stamp_defaults_to_a_dry_run_and_touches_nothing() {
    let (_guard, root) = staged("stamp");
    let citer = root.join("genesis/docs/superpowers/specs/citer.md");
    let before = sha256_of(&citer);
    let (code, out) = run_cites(&root, &["stamp", "--all"]);
    assert_eq!(code, 0, "{out}");
    assert!(out.contains("[DRY-RUN]"), "{out}");
    assert!(out.contains("status stamped: 4"), "{out}");
    assert_eq!(sha256_of(&citer), before, "a dry run wrote to disk");
}

#[test]
fn stamp_refuses_a_run_whose_slug_index_is_ambiguous() {
    // Refusal 5 — two documents declaring the same `id:` make every verdict on that slug
    // untrustworthy, so the WHOLE run is refused by name. The oracle silently resolved the
    // collision by walk order; this is a deliberate divergence toward refusing rather than guessing.
    let (_guard, root) = staged("dup-id");
    let (code, out) = run_cites(&root, &["stamp", "--all", "--write"]);
    assert_ne!(code, 0, "an ambiguous slug index must refuse: {out}");
    assert!(out.contains("duplicate id:"), "{out}");
    assert!(
        out.contains("twin"),
        "the refusal must name the colliding slug: {out}"
    );
    assert!(
        out.contains("one.md") && out.contains("two.md"),
        "the refusal must name both: {out}"
    );
}

#[test]
fn stamp_refuses_a_named_document_with_no_frontmatter() {
    // Refusal 1 — never synthesize a frontmatter block.
    let (_guard, root) = staged("stamp");
    let (code, out) = run_cites(
        &root,
        &[
            "stamp",
            "genesis/docs/superpowers/specs/no-frontmatter.md",
            "--write",
        ],
    );
    assert_ne!(code, 0, "{out}");
    assert!(out.contains("no frontmatter"), "{out}");
}

#[test]
fn stamp_skips_a_document_with_no_cites_key_silently() {
    // Refusal 2 — most documents have no `cites:` and that is not an error.
    let (_guard, root) = staged("stamp");
    let (code, out) = run_cites(
        &root,
        &[
            "stamp",
            "genesis/docs/superpowers/specs/no-cites.md",
            "--write",
        ],
    );
    assert_eq!(code, 0, "{out}");
    assert!(out.contains("docs touched: 0"), "{out}");
    assert!(!out.contains("refused"), "{out}");
}

