#[test]
fn migrate_reports_the_oracle_counts_on_the_fixture_corpus() {
    // `cites-migrate.py` on this fixture, measured 2026-09-10:
    //   5 docs · pass 1: 3 assigned (2 already had one) · pass 2: 2 converted across 1 docs
    let (_guard, root) = staged("migrate");
    let (code, out) = run_cites(&root, &["migrate"]);
    assert_eq!(code, 0, "{out}");
    assert!(out.contains("[DRY-RUN]: 5 docs"), "{out}");
    assert!(
        out.contains("pass 1: 3 id: slugs assigned (2 already had one)"),
        "{out}"
    );
    assert!(
        out.contains("pass 2: 2 cites converted to envelopes across 1 docs"),
        "{out}"
    );
}

#[test]
fn migrate_dry_run_writes_nothing() {
    let (_guard, root) = staged("migrate");
    let plan = root.join("genesis/docs/superpowers/plans/plan-one.md");
    let before = sha256_of(&plan);
    run_cites(&root, &["migrate"]);
    assert_eq!(sha256_of(&plan), before, "a migrate dry run wrote to disk");
}

#[test]
fn migrate_apply_drains_the_corpus_to_zero_pending() {
    let (_guard, root) = staged("migrate");
    let (code, out) = run_cites(&root, &["migrate", "--apply"]);
    assert_eq!(code, 0, "{out}");
    assert!(out.contains("[APPLIED]"), "{out}");
    let (code, out) = run_cites(&root, &["migrate"]);
    assert_eq!(code, 0, "{out}");
    assert!(
        out.contains("pass 1: 0 id: slugs assigned (5 already had one)"),
        "{out}"
    );
    assert!(
        out.contains("pass 2: 0 cites converted to envelopes across 0 docs"),
        "{out}"
    );

    // The minted envelope is byte-identical to the oracle's, INCLUDING its unquoted form:
    // `cites-migrate.py` does not YAML-quote what it mints, while `cite-gen --into` does, and the
    // corpus carries both. Reproducing that divergence is what makes a migrate pass comparable.
    let plan = std::fs::read_to_string(root.join("genesis/docs/superpowers/plans/plan-one.md"))
        .expect("read migrated plan");
    assert!(
        plan.contains(
            "  - target-a | Target A | sha256:2530afdb1630ffb4 | path: genesis/docs/superpowers/specs/target-a.md"
        ),
        "{plan}"
    );
    assert!(
        plan.contains(
            "  - target-b | Target B | sha256:b9f22c8ad5f2f2a5 | path: genesis/docs/superpowers/specs/target-b.md"
        ),
        "a title's first dash-segment is the migration-default description:\n{plan}"
    );
    assert!(
        plan.contains("  - elohim/elohim-storage/src/db/mod.rs"),
        "a code path cite must stay legacy:\n{plan}"
    );
}

#[test]
fn live_corpus_migrate_reports_zero_pending() {
    // The dissolution gate the plan names: the four Python cite scripts delete only after a corpus
    // dry run reports zero. Measured against `cites-migrate.py` before the drain (899 docs · 226
    // ids · 10 conversions across 7 docs — identical on both implementations), then drained.
    let root = repo_root();
    if !root.join("genesis/docs").is_dir() {
        return; // not a live checkout; the fixture legs carry the parity claim
    }
    let (code, out) = run_cites(&root, &["migrate"]);
    assert_eq!(code, 0, "{out}");
    assert!(
        out.contains("pass 1: 0 id: slugs assigned"),
        "the corpus has re-accumulated un-slugged documents; run `epr flow cites migrate --apply`:\n{out}"
    );
    assert!(
        out.contains("pass 2: 0 cites converted"),
        "the corpus has re-accumulated legacy doc cites; run `epr flow cites migrate --apply`:\n{out}"
    );
}

// ---------------------------------------------------------------------------
// The reader divergences the corpus forced
// ---------------------------------------------------------------------------

#[test]
fn an_empty_inline_cites_sequence_declares_no_cites() {
    // `cites: []` is nine live documents. The oracle stores it as the scalar `"[]"`, iterates the
    // string, and mints two phantom edges named `[` and `]` — 18 of the 22 `dead` verdicts its
    // 2026-09-10 corpus pass reported. Refused: a bracket is not a citation.
    let dir = tempfile::tempdir().expect("tempdir");
    let root = dir.path();
    let doc = root.join("genesis/docs/superpowers/specs/empty.md");
    std::fs::create_dir_all(doc.parent().unwrap()).unwrap();
    std::fs::write(
        &doc,
        "---\ntitle: Empty\nid: empty\ncites: []\n---\n\nBody.\n",
    )
    .unwrap();
    let (code, out) = run_cites(root, &["stamp", "--all", "--write"]);
    assert_eq!(code, 0, "{out}");
    assert!(
        out.contains("status stamped: 0"),
        "phantom bracket edges were stamped:\n{out}"
    );
    assert_eq!(
        std::fs::read_to_string(&doc).unwrap(),
        "---\ntitle: Empty\nid: empty\ncites: []\n---\n\nBody.\n",
        "the document was rewritten"
    );
}

#[test]
fn describe_sets_authored_hints_without_disturbing_the_envelope() {
    let (_guard, root) = staged("stamp");
    let citer = "genesis/docs/superpowers/specs/citer.md";
    let (code, out) = run_cites(
        &root,
        &[
            "describe",
            citer,
            "--slug",
            "ok-target",
            "--desc",
            "an authored relationship hint",
        ],
    );
    assert_eq!(code, 0, "{out}");
    assert!(out.contains("1 description(s) set"), "{out}");
    let text = std::fs::read_to_string(root.join(citer)).unwrap();
    let line = text.lines().find(|l| l.contains("ok-target |")).unwrap();
    assert!(line.contains("an authored relationship hint"), "{line}");
    assert!(
        line.contains("sha256:"),
        "the fingerprint was disturbed: {line}"
    );
    assert!(
        line.contains("path: genesis/docs/superpowers/specs/ok-target.md"),
        "{line}"
    );
    // Idempotent: a second identical run sets nothing.
    let (_, out) = run_cites(
        &root,
        &[
            "describe",
            citer,
            "--slug",
            "ok-target",
            "--desc",
            "an authored relationship hint",
        ],
    );
    assert!(out.contains("0 description(s) set"), "{out}");
}

#[test]
fn describe_accepts_the_oracle_positional_json_shape() {
    let (_guard, root) = staged("stamp");
    let citer = "genesis/docs/superpowers/specs/citer.md";
    let (code, out) = run_cites(
        &root,
        &[
            "describe",
            citer,
            "{\"stale-target\": \"a hint via the json shape\"}",
        ],
    );
    assert_eq!(code, 0, "{out}");
    assert!(out.contains("1 description(s) set"), "{out}");
}

#[test]
fn assign_id_is_idempotent_and_inserts_after_the_title() {
    let dir = tempfile::tempdir().expect("tempdir");
    let root = dir.path();
    let doc = root.join("genesis/docs/superpowers/specs/2026-01-01-fresh-design.md");
    std::fs::create_dir_all(doc.parent().unwrap()).unwrap();
    std::fs::write(
        &doc,
        "---\nstatus: proposed\ntitle: Fresh\nclass: devflow\n---\n\nBody.\n",
    )
    .unwrap();
    let (code, out) = run_cites(
        root,
        &[
            "assign-id",
            "genesis/docs/superpowers/specs/2026-01-01-fresh-design.md",
        ],
    );
    assert_eq!(code, 0, "{out}");
    assert_eq!(
        std::fs::read_to_string(&doc).unwrap(),
        "---\nstatus: proposed\ntitle: Fresh\nid: fresh-design\nclass: devflow\n---\n\nBody.\n"
    );
    let before = sha256_of(&doc);
    run_cites(
        root,
        &[
            "assign-id",
            "genesis/docs/superpowers/specs/2026-01-01-fresh-design.md",
        ],
    );
    assert_eq!(sha256_of(&doc), before, "assign-id is not idempotent");
}
